                )
            )
        return NativeDocument(
            source_url=url,
            source_kind=SourceKind.HUGGING_FACE,
            name=str(payload.get("id", namespace)),
            revision=str(payload.get("sha", "")),
            license_id=card.get("license"),
            text=str(payload.get("description") or card),
            files=files,
        )
