from __future__ import annotations

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol

import httpx
from pydantic import BaseModel, ConfigDict, Field, ValidationError

from .contracts import ApprovedManifest, AssetRole, ManifestContractError, parse_manifest
from .jobs import IngestionJob, IngestionJobConflict, IngestionJobStore, IngestionState


class ApprovedSourceResolutionError(ValueError):
    pass


class CreateIngestion(BaseModel):
    model_config = ConfigDict(alias_generator=lambda value: _to_camel(value), populate_by_name=True)

    approved_source_id: str = Field(pattern=r"^src_[a-f0-9]{24}$")
    asset_ids: list[str] | None = Field(default=None, min_length=1, max_length=500)


def _to_camel(value: str) -> str:
    head, *tail = value.split("_")
    return head + "".join(part.title() for part in tail)


def canonical_payload_sha256(payload: dict) -> str:
    canonical = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(canonical.encode()).hexdigest()


@dataclass(frozen=True)
class ResolvedApprovedSource:
    approved_source_id: str
    manifest_sha256: str
    manifest: ApprovedManifest


class ApprovedSourceResolver(Protocol):
    def resolve(self, approved_source_id: str) -> ResolvedApprovedSource: ...

    def close(self) -> None: ...


class _ApprovedSourceLookup(BaseModel):
    model_config = ConfigDict(alias_generator=_to_camel, populate_by_name=True, extra="ignore")

    approved_source_id: str = Field(pattern=r"^src_[a-f0-9]{24}$")
    latest_manifest_sha256: str = Field(pattern=r"^[a-f0-9]{64}$")
    is_acquisition_ready: bool


class HttpApprovedSourceResolver:
    def __init__(
        self,
        base_url: str,
        client: httpx.Client | None = None,
    ):
        self.base_url = base_url.rstrip("/")
        self.client = client or httpx.Client(timeout=5.0, follow_redirects=False)
        self._owns_client = client is None

    def close(self) -> None:
        if self._owns_client:
            self.client.close()

    def _json(self, path: str) -> dict:
        try:
            response = self.client.get(f"{self.base_url}{path}")
            response.raise_for_status()
            payload = response.json()
        except (httpx.HTTPError, json.JSONDecodeError) as exc:
            raise ApprovedSourceResolutionError("Approved source service is unavailable") from exc
        if not isinstance(payload, dict):
            raise ApprovedSourceResolutionError("Approved source service returned invalid data")
        return payload

    def resolve(self, approved_source_id: str) -> ResolvedApprovedSource:
        detail_payload = self._json(f"/api/approved-sources/{approved_source_id}")
        manifest_payload = self._json(
            f"/api/approved-sources/{approved_source_id}/manifest"
        )
        try:
            detail = _ApprovedSourceLookup.model_validate(detail_payload)
        except ValidationError as exc:
            raise ApprovedSourceResolutionError(
                "Approved source service returned an invalid source summary"
            ) from exc
        if detail.approved_source_id != approved_source_id:
            raise ApprovedSourceResolutionError("Approved source identity did not match the request")
        if not detail.is_acquisition_ready:
            raise ApprovedSourceResolutionError("Approved source lacks acquisition metadata")
        actual_sha256 = canonical_payload_sha256(manifest_payload)
        if actual_sha256 != detail.latest_manifest_sha256:
            raise ApprovedSourceResolutionError("Approved source manifest integrity check failed")
        try:
            manifest = parse_manifest(manifest_payload)
        except ManifestContractError as exc:
            raise ApprovedSourceResolutionError(str(exc)) from exc
        return ResolvedApprovedSource(
            approved_source_id=approved_source_id,
            manifest_sha256=actual_sha256,
            manifest=manifest,
        )


class IngestionService:
    def __init__(
        self,
        data_dir: Path,
        resolver: ApprovedSourceResolver,
    ):
        self.jobs = IngestionJobStore(data_dir / "ingestions.sqlite3")
        self.resolver = resolver

    def close(self) -> None:
        self.jobs.close()
        self.resolver.close()

    def create(self, request: CreateIngestion) -> tuple[IngestionJob, bool]:
        existing = self.jobs.find_by_source(request.approved_source_id)
        if existing is not None:
            if request.asset_ids is not None and sorted(set(request.asset_ids)) != existing.asset_ids:
                raise IngestionJobConflict(
                    "Approved source already has an ingestion with another asset selection"
                )
            return existing, False

        resolved = self.resolver.resolve(request.approved_source_id)
        data_asset_ids = {
            asset.asset_id
            for asset in resolved.manifest.assets
            if asset.role is AssetRole.DATA
        }
        selected = sorted(request.asset_ids or data_asset_ids)
        if len(selected) != len(set(selected)):
            raise IngestionJobConflict("Asset selection contains duplicate IDs")
        if not selected or any(asset_id not in data_asset_ids for asset_id in selected):
            raise IngestionJobConflict("Asset selection must contain only approved data assets")

        has_dataset_license = bool(resolved.manifest.dataset_license_id)
        state = IngestionState.QUEUED if has_dataset_license else IngestionState.NEEDS_INPUT
        message = (
            "Queued for verified acquisition"
            if has_dataset_license
            else "Dataset-file license must be confirmed before acquisition"
        )
        return self.jobs.get_or_create(
            approved_source_id=request.approved_source_id,
            manifest_sha256=resolved.manifest_sha256,
            source_url=str(resolved.manifest.canonical_url).rstrip("/"),
            source_kind=resolved.manifest.source_kind.value,
            source_revision=resolved.manifest.source_revision,
            asset_ids=selected,
            state=state,
            message=message,
        )

from __future__ import annotations

import logging
import os
from collections.abc import AsyncIterator
from contextlib import asynccontextmanager
from pathlib import Path

from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse

from .jobs import IngestionJob, IngestionJobConflict, IngestionJobNotFound
from .service import (
    ApprovedSourceResolutionError,
    CreateIngestion,
    HttpApprovedSourceResolver,
    IngestionService,
)

LOGGER = logging.getLogger(__name__)


def _error(status: int, code: str, message: str, *, details=None) -> JSONResponse:
    return JSONResponse(
        status_code=status,
        content={
            "error": {
                "code": code,
                "message": message,
                "retryable": False,
                "details": details,
            }
        },
    )


def create_app(service: IngestionService | None = None) -> FastAPI:
    owns_service = service is None
    ingestion = service or IngestionService(
        data_dir=Path(os.environ.get("INGESTION_DATA_DIR", "var/ingestion")),
        resolver=HttpApprovedSourceResolver(
            os.environ.get("INGESTION_SOURCING_API_URL", "http://127.0.0.1:8000")
        ),
    )

    @asynccontextmanager
    async def lifespan(_: FastAPI) -> AsyncIterator[None]:
        yield
        if owns_service:
            ingestion.close()

    app = FastAPI(title="Approved Dataset Ingestion", version="0.1.0", lifespan=lifespan)
    app.state.ingestion = ingestion

    @app.middleware("http")
    async def security_headers(request: Request, call_next):
        response = await call_next(request)
        response.headers["X-Content-Type-Options"] = "nosniff"
        response.headers["Cache-Control"] = "no-store"
        return response

    @app.exception_handler(RequestValidationError)
    async def invalid_request(_: Request, exc: RequestValidationError) -> JSONResponse:
        details = [
            {"location": list(error["loc"]), "message": error["msg"]} for error in exc.errors()
        ]
        return _error(422, "INVALID_REQUEST", "Request validation failed", details=details)

    @app.exception_handler(IngestionJobConflict)
    async def ingestion_conflict(_: Request, exc: IngestionJobConflict) -> JSONResponse:
        return _error(409, "INGESTION_CONFLICT", str(exc))

    @app.exception_handler(IngestionJobNotFound)
    async def ingestion_not_found(_: Request, exc: IngestionJobNotFound) -> JSONResponse:
        return _error(404, "INGESTION_NOT_FOUND", str(exc))

    @app.exception_handler(ApprovedSourceResolutionError)
    async def source_unavailable(_: Request, exc: ApprovedSourceResolutionError) -> JSONResponse:
        return _error(422, "APPROVED_SOURCE_UNAVAILABLE", str(exc))

    @app.exception_handler(Exception)
    async def unhandled_error(_: Request, exc: Exception) -> JSONResponse:
        LOGGER.exception("Unhandled ingestion API error", exc_info=exc)
        return _error(500, "INTERNAL_ERROR", "An unexpected server error occurred")

    @app.post("/api/ingestions", response_model=IngestionJob, status_code=202)
    def create_ingestion(body: CreateIngestion) -> IngestionJob:
        job, _ = ingestion.create(body)
        return job

    @app.get("/api/ingestions/{ingestion_id}", response_model=IngestionJob)
    def get_ingestion(ingestion_id: str) -> IngestionJob:
        return ingestion.jobs.get(ingestion_id)

    return app

from __future__ import annotations

import hashlib
import ipaddress
import socket
import tempfile
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlsplit

import httpx

from .contracts import ChecksumAlgorithm, ManifestAsset, SourceKind


class AcquisitionError(RuntimeError):
    pass


@dataclass(frozen=True)
class AcquiredAsset:
    asset_id: str
    size_bytes: int
    content_sha256: str
    content_path: Path


def _validate_zenodo_url(raw_url: str, *, validate_dns: bool) -> None:
    parsed = urlsplit(raw_url)
    if (
        parsed.scheme != "https"
        or (parsed.hostname or "").casefold() not in {"zenodo.org", "www.zenodo.org"}
        or parsed.username
        or parsed.password
        or parsed.port not in (None, 443)
    ):
        raise AcquisitionError("Zenodo asset URL is not allowlisted")
    if not validate_dns:
        return
    try:
        records = socket.getaddrinfo(parsed.hostname, 443, type=socket.SOCK_STREAM)
        addresses = {record[4][0] for record in records}
    except OSError as exc:
        raise AcquisitionError("Zenodo host could not be resolved") from exc
    if not addresses or any(not ipaddress.ip_address(address).is_global for address in addresses):
        raise AcquisitionError("Zenodo host resolved to a non-public address")


class ZenodoAcquirer:
    def __init__(
        self,
        cache_dir: Path,
        *,
        max_asset_bytes: int = 25_000_000_000,
        client: httpx.Client | None = None,
        validate_dns: bool = True,
    ):
        self.cache_dir = cache_dir.resolve()
        self.staging_dir = self.cache_dir / "staging"
        self.content_dir = self.cache_dir / "content"
        self.staging_dir.mkdir(parents=True, exist_ok=True)
        self.content_dir.mkdir(parents=True, exist_ok=True)
        self.max_asset_bytes = max_asset_bytes
        self.client = client or httpx.Client(timeout=30.0, follow_redirects=False)
        self._owns_client = client is None
        self.validate_dns = validate_dns

    def close(self) -> None:
        if self._owns_client:
            self.client.close()

    def acquire(self, source_kind: SourceKind, asset: ManifestAsset) -> AcquiredAsset:
        if source_kind is not SourceKind.ZENODO:
            raise AcquisitionError("Zenodo acquirer received another provider")
        if asset.size_bytes > self.max_asset_bytes:
            raise AcquisitionError("Asset exceeds the configured download limit")
        url = str(asset.download_url)
        _validate_zenodo_url(url, validate_dns=self.validate_dns)
        temporary_path: Path | None = None
        sha256 = hashlib.sha256()
        provider_hash = (
            hashlib.md5(usedforsecurity=False)
            if asset.source_checksum
            and asset.source_checksum.algorithm is ChecksumAlgorithm.MD5
            else hashlib.sha256()
            if asset.source_checksum
            and asset.source_checksum.algorithm is ChecksumAlgorithm.SHA256
            else None
        )
        size = 0
        try:
            with self.client.stream("GET", url) as response:
                if response.is_redirect:
                    raise AcquisitionError("Zenodo download redirected unexpectedly")
                response.raise_for_status()
                declared = response.headers.get("Content-Length")
                if declared is not None and int(declared) != asset.size_bytes:
                    raise AcquisitionError("Zenodo content length differs from the approved manifest")
                with tempfile.NamedTemporaryFile(dir=self.staging_dir, delete=False) as output:
                    temporary_path = Path(output.name)
                    for chunk in response.iter_bytes():
                        size += len(chunk)
                        if size > asset.size_bytes or size > self.max_asset_bytes:
                            raise AcquisitionError("Zenodo download exceeded the approved size")
                        output.write(chunk)
                        sha256.update(chunk)
                        if provider_hash is not None:
                            provider_hash.update(chunk)
            if size != asset.size_bytes:
                raise AcquisitionError("Zenodo download was truncated")
            if (
                asset.source_checksum
                and provider_hash is not None
                and provider_hash.hexdigest() != asset.source_checksum.value
            ):
                raise AcquisitionError("Zenodo provider checksum did not match")
            digest = sha256.hexdigest()
            target_dir = self.content_dir / digest[:2]
            target_dir.mkdir(parents=True, exist_ok=True)
            target = target_dir / digest
            if target.exists():
                if target.stat().st_size != size:
                    raise AcquisitionError("Cached content failed its size check")
            else:
                temporary_path.replace(target)
                temporary_path = None
            return AcquiredAsset(
                asset_id=asset.asset_id,
                size_bytes=size,
                content_sha256=digest,
                content_path=target,
            )
        except httpx.HTTPError as exc:
            raise AcquisitionError("Zenodo download failed") from exc
        finally:
            if temporary_path is not None:
                temporary_path.unlink(missing_ok=True)

